      "title": "Secure Boot is not enabled",
      "resource": "azurerm_windows_virtual_machine_scale_set.negative4",
      "severity": "MEDIUM",
      "explanation": "The scale set does not enable Trusted Launch or Secure Boot, leaving guest boot components without cryptographic integrity verification."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Virtual TPM is not enabled",
      "resource": "azurerm_windows_virtual_machine_scale_set.negative4",
      "severity": "MEDIUM",
      "explanation": "The scale set does not enable a virtual TPM, reducing protection for measured boot and other hardware-backed security capabilities."
    }
  ],
  "patched_code": "resource \"azurerm_windows_virtual_machine_scale_set\" \"negative4\" {\n  name                 = \"negative4-vmss\"\n  resource_group_name  = azurerm_resource_group.negative4.name\n  location             = azurerm_resource_group.negative4.location\n  sku                  = \"Standard_F2\"\n  computer_name_prefix = \"vm-\"\n\n  security_type              = \"TrustedLaunch\"\n  secure_boot_enabled        = true\n  vtpm_enabled               = true\n  encryption_at_host_enabled = true\n}\n",
  "fix_summary": "Enabled Trusted Launch, Secure Boot, and virtual TPM protections. Existing host-level encryption remains enabled."
}
